command:example.dev:code:
# Экспортируйте и сравните с предыдущей резервной копией.
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "Новые скрипты: $($new.Count) | Удалены скрипты: $($removed.Count)"

dev:remarks.maml:para:
Получает разрешенный каталог кэша. `Cache.Path` остается необязательным переопределением, настраиваемым пользователем;
`Cache.EffectivePath` показывает каталог, который модуль фактически использует после настроек платформы по умолчанию и
применяются переопределения среды.

command:example.dev:code:
$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "Настроен пользовательский путь кеширования: $($config.Cache.Path)."
} else {
    Write-Host "Использование пути к кэшу по умолчанию"
}

Write-Host "Эффективный путь кеширования: $($config.Cache.EffectivePath)."

# Создайте кеш для отфильтрованных скриптов.
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# Найдите первый скрипт, соответствующий шаблону, для быстрого отображения.
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# Прежде чем запускать автоматизацию, убедитесь, что все указанные сценарии существуют.
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "Отсутствующие скрипты: $($missing -join ', ')"
} else {
    Write-Host "Все необходимые скрипты имеются."
}

# Создание нескольких цветовых сценариев для проекта
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "Создано $($scriptNames.Count) шаблонов цветных сценариев."

# Проверьте соглашения об именах сценариев.
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "Неверное имя «$name»: $_."
    }
}

# Создать с проверкой категорий и тегов
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "Категория ретро не найдена"
}

# Убедитесь, что сброс прошел успешно
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "Конфигурация успешно сброшена до значений платформы по умолчанию."
} else {
    Write-Host "Сброс конфигурации, но с использованием пользовательского пути: $($config.Cache.Path)"
}

# Создайте слайд-шоу из геометрических цветовых сценариев.
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# Пример обработки ошибок
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "Сценарий не найден: $_"
    Show-ColorScript  # Возврат к случайному выбору
}

# Интеграция автоматизации сборки
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # Случайное отображение для интерактивного использования
}

# Запланированная задача для приветствия терминала
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
